<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            font-family: "Times New Roman", serif;
            margin: 0;
            padding: 0;
            line-height: 1.4;
            color: #000;
            background: #fff;
        }

        .page {
            width: 8.5in;
            min-height: 11in;
            margin: 20px auto;
            padding: 40px 50px 40px 50px;
            box-sizing: border-box;
            border: 1px solid #ccc;
            background: #fff;
            position: relative;
        }

        .header {
            text-align: center;
            margin-bottom: 20px;
            font-size: 14pt;
            font-weight: bold;
        }

        .column {
            display: flex;
            gap: 30px;
            margin-bottom: 25px;
        }

        .col {
            flex: 1;
            font-size: 12pt;
        }

        .left-col {
            margin-right: 15px;
        }

        .right-col {
            border-left: 1px solid #999;
            padding-left: 20px;
        }

        .title {
            font-size: 24pt;
            font-weight: bold;
            text-align: center;
            margin: 30px 0 15px;
        }

        .section {
            font-weight: bold;
            font-size: 14pt;
            margin: 18px 0 6px;
        }

        .section-number {
            color: #000;
            font-weight: bold;
        }

        .item {
            margin-left: 25px;
            margin-bottom: 4px;
        }

        .item:last-child {
            margin-bottom: 0;
        }

        .placeholder {
            width: 100%;
            height: 120px;
            margin: 15px 0;
            background: #f0f0f0;
            border: 1px dashed #999;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11pt;
            color: #666;
            text-align: center;
            position: relative;
        }

        .placeholder-caption {
            position: absolute;
            top: 5px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(255,255,255,0.85);
            padding: 2px 8px;
            font-size: 10pt;
            font-style: italic;
        }

        .footer {
            margin-top: 40px;
            text-align: center;
            font-size: 10pt;
            color: #555;
        }

        .signature {
            margin-top: 30px;
            text-align: right;
            font-size: 12pt;
        }
    </style>
</head>
<body>
    <div class="page">
        <!-- Header -->
        <div class="header">
            [Header text: centered, bold, 14pt]
        </div>

