        <div class="title">
            [Document Title: centered, 24pt]
        </div>

        <!-- Introduction -->
        <p>
            [Introductory paragraph text: left-aligned, 12pt]
        </p>

        <!-- Section 1 -->
        <div class="section">
            <span class="section-number">1.</span> Section Title
